const htmlBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const raw = htmlBuffer.toString('utf8');

let state;
try {
  state = JSON.parse(raw);
} catch (e) {
  return [{ json: { shouldExpire: false, shouldRemind: false, skipReason: 'json invalido' } }];
}

const stateFileName = $input.item.binary.data.fileName || '';
const now = Date.now();
const expiresAtMs = state.expires_at ? new Date(state.expires_at).getTime() : NaN;
const isPreviewComExpiracao = state.estado === 'preview' && !isNaN(expiresAtMs);

// N2 -- lembrete 3h antes de expirar. Janela [2h30, 3h30] em vez de "== 3h"
// porque o cron corre de hora a hora e nunca vai acertar o minuto exato de
// qualquer expires_at. lembrete_enviado (ausente = false = elegivel) impede
// reenvio na proxima passagem depois de um envio bem sucedido -- ver
// "Marca Lembrete Enviado", que so grava a flag quando o Gmail confirma o
// envio (id presente na resposta), para uma falha de envio poder tentar de
// novo na proxima hora em vez de ficar silenciosamente por enviar.
const MS_HORA = 3600 * 1000;
const msParaExpirar = expiresAtMs - now;
const shouldRemind = isPreviewComExpiracao && !state.lembrete_enviado &&
  msParaExpirar > 2.5 * MS_HORA && msParaExpirar <= 3.5 * MS_HORA;

const isExpired = isPreviewComExpiracao && expiresAtMs < now;

if (!isExpired) {
  return [{ json: { shouldExpire: false, shouldRemind, landingId: state.landing_id, stateFileName, state } }];
}

state.estado = 'expirado';

function escapeHtml(unsafe) {
  if (!unsafe) return '';
  return String(unsafe).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#039;");
}
const corretorNome = escapeHtml(state.cliente?.corretor?.nome || '');
const corretorWa = String(state.cliente?.corretor?.whatsapp || '').replace(/\D/g, '');
const titulo = escapeHtml(state.imovel?.titulo || 'Este imóvel');
const waLink = 'https://wa.me/' + corretorWa + '?text=' + encodeURIComponent('Olá, a pré-visualização de "' + (state.imovel?.titulo || '') + '" expirou. Gostava de a reativar.');

const expiredHtml = `<!DOCTYPE html>
<html lang="pt">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Pré-visualização expirada</title>
<meta name="robots" content="noindex">
<style>
  body{font-family:system-ui,sans-serif;background:#0f172a;color:#f8fafc;display:flex;min-height:100vh;align-items:center;justify-content:center;margin:0;padding:1.5rem;text-align:center}
  .box{max-width:32rem}
  h1{font-size:1.5rem;margin-bottom:.75rem}
  p{color:#94a3b8;margin-bottom:1.5rem;line-height:1.6}
  a{display:inline-flex;align-items:center;gap:.5rem;padding:.9rem 1.5rem;border-radius:.5rem;background:#25D366;color:#062611;font-weight:600;text-decoration:none}
</style>
</head>
<body>
  <div class="box">
    <h1>A pré-visualização de "${titulo}" expirou</h1>
    <p>Esta landing estava em modo de pré-visualização e o prazo terminou sem confirmação de publicação. Contacte ${corretorNome || 'o corretor'} para a reativar.</p>
    <a href="${waLink}">Reativar via WhatsApp</a>
  </div>
</body>
</html>`;

const htmlFileName = stateFileName.replace('.state.json', '.html');
const stateFileNameOut = stateFileName;

const outHtmlBinary = await this.helpers.prepareBinaryData(Buffer.from(expiredHtml, 'utf8'), htmlFileName.split('/').pop(), 'text/html');
const outStateBinary = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(state, null, 2), 'utf8'), stateFileNameOut.split('/').pop(), 'application/json');

return [{
  json: { shouldExpire: true, shouldRemind: false, landingId: state.landing_id, htmlPath: '/home/node/.n8n-files/builds/' + htmlFileName.split('/').pop(), statePath: '/home/node/.n8n-files/builds/' + stateFileNameOut.split('/').pop(), state },
  binary: { data: outHtmlBinary, state: outStateBinary }
}];

// N2 -- lembrete 3h antes de expirar (alimentado por "Se Deve Lembrar",
// que ja filtrou shouldRemind === true a partir de "Verifica Expiracao").
// ===== PRISMA CONFIG CENTRAL (N5, replicado -- ver nota em imovel-landing-wf.json) =====
const PRISMA_BRAND_NAME = 'Prisma';
const PRISMA_CONTACT_WHATSAPP = '+351920000000';
const PRISMA_OPERATOR_EMAIL = 'ibissonsilva@gmail.com';
function prismaPaymentLink(titulo, imobiliaria, landingId) {
  return 'https://wa.me/' + PRISMA_CONTACT_WHATSAPP.replace(/\D/g, '') + '?text=' + encodeURIComponent(
    'Prisma Studio: quero publicar a landing "' + titulo + '" (imobiliária: ' + imobiliaria + ', landing_id: ' + landingId + ').'
  );
}

function escapeHtml(unsafe) {
  if (unsafe === undefined || unsafe === null) return '';
  return String(unsafe).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#039;");
}
function escapeAttr(unsafe) {
  if (unsafe === undefined || unsafe === null) return '';
  return String(unsafe).replace(/"/g, "&quot;").replace(/'/g, "&#039;");
}

// N4 -- template de email (replicado, ver nota em imovel-landing-wf.json).
function buildEmailPrisma({ brandName, preheader, headline, bodyHtml, ctaLabel, ctaUrl }) {
  const brand = escapeHtml(brandName || PRISMA_BRAND_NAME);
  const fontStack = `-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif`;
  const ctaBlock = ctaUrl ? `
    <table role="presentation" cellpadding="0" cellspacing="0" style="margin-top:24px;">
      <tr><td style="border-radius:6px;background-color:#8c6d4f;">
        <a href="${escapeAttr(ctaUrl)}" style="display:inline-block;padding:14px 28px;font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;font-family:${fontStack};">${escapeHtml(ctaLabel || '')}</a>
      </td></tr>
    </table>` : '';
  return `<!DOCTYPE html>
<html lang="pt">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${brand}</title>
</head>
<body style="margin:0;padding:0;background-color:#f4f2ef;font-family:${fontStack};">
<span style="display:none;font-size:1px;color:#f4f2ef;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;">${escapeHtml(preheader || '')}</span>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f2ef;padding:32px 16px;"><tr><td align="center">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background-color:#ffffff;border-radius:8px;overflow:hidden;">
<tr><td style="background-color:#1c2421;padding:24px 32px;"><span style="font-size:20px;font-weight:600;color:#ffffff;letter-spacing:0.02em;font-family:${fontStack};">${brand}</span></td></tr>
<tr><td style="padding:32px 32px 8px;">
<h1 style="margin:0 0 16px;font-size:22px;line-height:1.3;color:#1c2421;font-family:${fontStack};">${escapeHtml(headline || '')}</h1>
<div style="font-size:15px;line-height:1.6;color:#3f3f3f;font-family:${fontStack};">${bodyHtml}</div>
${ctaBlock}
</td></tr>
<tr><td style="padding:20px 32px 28px;background-color:#f1ede6;border-top:1px solid #e5e0d8;">
<p style="margin:0;font-size:12px;color:#8a8a8a;line-height:1.5;font-family:${fontStack};">Esta é uma mensagem automática do ${brand}. Pode responder a este email diretamente com alterações ou dúvidas.</p>
</td></tr>
</table>
</td></tr></table>
</body>
</html>`;
}

const state = $json.state;
const imovelRaw = state.imovel || {};
const corretor = imovelRaw.corretor || (state.cliente && state.cliente.corretor) || {};
const titulo = imovelRaw.titulo || 'O seu imóvel';
const imobiliaria = imovelRaw.imobiliaria || (state.cliente && state.cliente.imobiliaria) || '';
const landingId = state.landing_id;
const canonical = state.url;

const corretorEmailRaw = String(corretor.email || '').trim();
const semEmailCorretor = !corretorEmailRaw;
const targetEmail = corretorEmailRaw || PRISMA_OPERATOR_EMAIL;

const expiresAtDate = new Date(state.expires_at);
const expiresDisplay = isNaN(expiresAtDate.getTime()) ? '' : expiresAtDate.toLocaleString('pt-PT', { timeZone: 'Europe/Lisbon', day: '2-digit', month: 'long', hour: '2-digit', minute: '2-digit' });

const paymentLink = prismaPaymentLink(titulo, imobiliaria, landingId);

const bodyHtml = `
<p>Este é um lembrete: a pré-visualização da página do imóvel <strong>${escapeHtml(titulo)}</strong> expira dentro de cerca de 3 horas${expiresDisplay ? ' (' + escapeHtml(expiresDisplay) + ', hora de Lisboa)' : ''}.</p>
<p style="margin:20px 0;"><a href="${escapeAttr(canonical)}" style="color:#8c6d4f;font-weight:600;word-break:break-all;">${escapeHtml(canonical)}</a></p>
<p>Se quiser manter esta página online sem interrupção, publique-a agora.</p>
<p style="margin-top:24px;">Encontrou algo para corrigir? Basta responder a este email a descrever a alteração.</p>
${semEmailCorretor ? '<p style="color:#b91c1c;"><strong>Nota interna:</strong> este envio foi feito para o email do operador porque o corretor não indicou um email no formulário.</p>' : ''}
`;

const html = buildEmailPrisma({
  brandName: PRISMA_BRAND_NAME,
  preheader: 'O seu preview expira em cerca de 3 horas.',
  headline: 'O seu preview expira em 3 horas',
  bodyHtml,
  ctaLabel: 'Publicar o meu site',
  ctaUrl: paymentLink
});

const subject = (semEmailCorretor ? '[SEM EMAIL DO CORRETOR] ' : '') + 'O seu preview expira em 3 horas — ' + titulo;

return [{ json: { targetEmail, subject, html, landingId } }];

// N2 -- so grava lembrete_enviado:true quando o Gmail confirma o envio (id
// presente na resposta do no anterior). Se o envio falhou, a flag fica por
// gravar e a proxima passagem horaria do cron tenta reenviar -- nunca marca
// "enviado" sem ter enviado de facto.
const src = $('Verifica Expiracao').item.json;
const state = src.state;
const gmailResp = $input.item.json || {};
const sentOk = !!gmailResp.id;

const baseName = String(src.stateFileName || '').split('/').pop();
const statePath = '/home/node/.n8n-files/builds/' + baseName;

if (sentOk) {
  state.lembrete_enviado = true;
  state.lembrete_enviado_em = new Date().toISOString();
}

const out = Buffer.from(JSON.stringify(state, null, 2), 'utf8');
return [{
  json: { statePath, lembreteMarcado: sentOk, gmailId: gmailResp.id || null },
  binary: { state: await this.helpers.prepareBinaryData(out, baseName, 'application/json') }
}];

// N3 -- email de expiracao, disparado no mesmo ramo que despublica a landing
// (paralelo a "Sobrescreve HTML Expirado"/"Atualiza State para Expirado" --
// uma falha no envio nunca bloqueia a despublicacao, que ja aconteceu nos
// ramos irmaos independentemente deste). Idempotente por construcao: depois
// desta passagem state.estado deixa de ser 'preview', por isso a condicao
// isExpired em "Verifica Expiracao" nunca volta a ser verdadeira para esta
// landing -- nao e preciso nenhuma flag extra tipo lembrete_enviado.
// ===== PRISMA CONFIG CENTRAL (N5, replicado -- ver nota em imovel-landing-wf.json) =====
